if(EditorApplication.isPlaying)throw new System.Exception("Edit mode required");var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var results=new System.Collections.Generic.List<object>();var temp=new System.Collections.Generic.List<GameObject>();
GameObject Obj(string name)=>all.First(t=>t.name==name&&(t.parent==null||t.parent.name!=name)).gameObject;
MeshCollider Support(string name){var m=all.Where(t=>t.name==name&&t.gameObject.activeInHierarchy).Select(t=>t.GetComponent<MeshFilter>()).FirstOrDefault(m=>m!=null&&m.sharedMesh!=null);if(m==null)throw new System.Exception("Visible support mesh missing: "+name);var g=new GameObject("Temporary visible support probe");temp.Add(g);g.transform.SetPositionAndRotation(m.transform.position,m.transform.rotation);g.transform.localScale=m.transform.lossyScale;var c=g.AddComponent<MeshCollider>();c.sharedMesh=m.sharedMesh;return c;}
void Check(Transform item,string support,float w,float h,float centreY,float back){var mesh=Support(support);var distances=new System.Collections.Generic.List<float>();bool okay=true;foreach(float x in new[]{-w*.45f,0,w*.45f})foreach(float y in new[]{centreY-h*.45f,centreY,centreY+h*.45f}){var q=item.TransformPoint(new Vector3(x,y,back));if(mesh.Raycast(new Ray(q+item.forward*.05f,-item.forward),out var hit,.075f)){float gap=hit.distance-.05f;distances.Add(gap);if(gap<-.006f||gap>.012f)okay=false;}else okay=false;}results.Add(new{item=item.name,support,passed=okay,gaps=distances});}
try{Check(Obj("CM_HR02_HerbariumBoard").transform,"Shop to kitchen 1.8 jamb A",.72f,.9f,0,-.02f);Check(Obj("CM_LI03_RecordShelf").transform,"Shop to kitchen 1.8 jamb A",1.28f,.76f,.38f,0);Check(Obj("CM_LI03_ReagentCabinet").transform,"Treatment to wing",1.18f,1.4f,.70f,0);Check(Obj("CM_LI03_ToolRail").transform,"Treatment to wing",1.12f,.11f,0,0);
Check(Obj("CM_LI03_FormularyBoard").transform,"Wing front ground",.84f,.50f,0,0);Check(Obj("CM_HR02_LimeRepair").transform,"Front entrance 2.0 jamb B",.50f,.48f,0,-.003f);
var shop=all.Single(t=>t.name=="CM_AF01_HerbDryingStation"&&t.parent.name.StartsWith("Shop"));Check(shop,"West shop front",1.4f,.07f,.56f,-.14f);var prep=all.Single(t=>t.name=="CM_AF01_HerbDryingStation"&&t.parent.name.StartsWith("Preparation"));Check(prep,"Wing front ground",1.4f,.07f,.56f,-.14f);
// A post-mounted plaque is supported centrally by its own solid backer, rather than requiring wall behind its cantilevered edges.
var plaque=Obj("CM_HR02_PracticePlaque").transform;var post=Support("01_Post_L");var centre=plaque.TransformPoint(new Vector3(0,0,-.025f));bool hitPost=post.Raycast(new Ray(centre+plaque.forward*.05f,-plaque.forward),out var ph,.075f);results.Add(new{item=plaque.name,support="01_Post_L",passed=hitPost&&Mathf.Abs(ph.distance-.05f)<.012f,gap=hitPost?ph.distance-.05f:999});
}catch(System.Exception e){results.Add(new{error=e.ToString()});}finally{foreach(var g in temp)UnityEngine.Object.DestroyImmediate(g);}
System.IO.File.WriteAllText("ArtSource/Blender/Interiors/CrookedMortar/LivedIn03/VisibleSupportValidation.json",Newtonsoft.Json.JsonConvert.SerializeObject(results,Newtonsoft.Json.Formatting.Indented));return results;
